from pathlib import Path
p=Path('manuscript/main.tex');s=p.read_text()
s=s.replace("on the GTDB-Tk R232 archaeal marker tree, normalising shared branch lengths to a correlation", "on an approximate maximum-likelihood FastTree phylogeny (LG+Gamma) from the GTDB-Tk R232 ar53 alignment \\citep{price2010fasttree}, normalising shared branch lengths to a correlation")
s=s.replace("We selected one locus per family and species\nby the outcome-independent ordering in the archived selection script.", "We selected one locus per family and species by descending complete-window eligibility, first\nfor exact-coordinate windows and then for the same-strand stop-match sensitivity. Ties used\ndescending counts of exact-mapped, exact-or-stop-mapped and present flanks, followed by contig\nlength and gene count, then ascending member identifier. This ordering uses mapping completeness\nand assembly properties independently of flanking orthologue identity.")
s=s.replace("The primary between-group comparison stratified families by species breadth, four coarse\nphylum groups and annotation opportunity; all 353 families belonged to the 16 strata with\nboth groups represented.", "The primary between-group comparison stratified families by two versus at least three\nevaluable species; host phylum (Thermoplasmatota, Actinomycetota, multiple phyla or other);\nand flanking annotation opportunity above versus at or below the pooled median. All 353\nfamilies belonged to the 16 strata with both groups represented. Each stratum's weight was\nthe product of its two group sizes divided by its total size. The positional null sampled\nuniformly from complete-window-eligible gene positions on the same contig, including the\nobserved focal position when eligible. Python random seeds were 20261013 for positional draws,\n20261014 for primary label permutations and 20261015 for the stop-match sensitivity.")
s=s.replace("(68.0\\%) with no hit in either, a triage rather than a result.", "(68.0\\%) with no hit in either, forming the candidates for coordinate-based validation.")
s=s.replace("confidence.\n\nCo-searched", "confidence.\n\nCo-searched")
s=s.replace("This conditional comparison\nselects on retrieval and does not calibrate all search failures.", "This conditional comparison describes retrieved alignments; the primary denominator retains\nall qualified models and includes retrieval failures.")
# Order supplementary notes by first citation and then order their physical sections.
s=s.replace('Supplementary Note S1','Supplementary Note TEMP').replace('Supplementary Note S3','Supplementary Note S1').replace('Supplementary Note TEMP','Supplementary Note S3')
a=s.index('\\section*{Supplementary Note S3:');b=s.index('\\section*{Supplementary Note S2:',a);c=s.index('\\section*{Supplementary Note S1:',b);d=s.index('\\section*{Data and code availability}',c)
s=s[:a]+s[c:d]+s[b:c]+s[a:b]+s[d:]
s=s.replace('Confident regions recover matches missed by whole-chain structural queries', 'Confident regions recover structural reference matches')
s=s.replace('Reference coverage limits interpretation of microbial gene content.', 'Reference coverage limits interpretation of microbial proteomes.')
s=s.replace('The catalogue connects reference-absent gene content\nto genomes and repeated environmental sampling, while the controls identify how reference\ncomposition and query definition shape the unknown proteome.', 'Our catalogue connects reference-absent proteins to genomes and repeated sampling, with controls\nidentifying how reference composition and query definition shape unknown proteomes.')
p.write_text(s)
